local ui=require("ui");local cfg=require("config");local M={};local scales={0.5,1,1.5,2,2.5,3,3.5,4,4.5,5}
function M.run(m,c) while true do ui.clear(m);ui.header(m,"DISPLAY SETTINGS");local w,h=m.getSize();m.setCursorPos(2,3);m.write("Scale: "..tostring(m.getTextScale()));for i,s in ipairs(scales) do local col=(i-1)%2;local row=math.floor((i-1)/2);local x=2+col*math.floor(w/2);local y=5+row*2;if y<h then ui.btn(m,x,y,math.floor(w/2)-3,tostring(s).."x",false) end end;ui.back(m);local _,x,y=os.pullEvent("monitor_touch");if y==h and x<=10 then return end;for i,s in ipairs(scales) do local col=(i-1)%2;local row=math.floor((i-1)/2);local bx=2+col*math.floor(w/2);local by=5+row*2;if x>=bx and x<bx+math.floor(w/2)-3 and y==by then if pcall(m.setTextScale,s) then c.scale=s;cfg.save(c) end end end end end
return M
